mapper.sql:
WHERE p.deleted_at IS NULL
AND p.company_id = #{companyId}

    AND EXISTS (SELECT 1
    FROM project_member pm
    WHERE pm.project_id = p.project_id
    AND pm.user_id = #{requesterUserId}
    AND pm.permission <> 'NONE')

AND p.status = #{status}

    AND EXISTS (SELECT 1
    FROM project_business_category pbc
    WHERE pbc.project_id = p.project_id
    AND pbc.business_category_id = #{businessCategoryId})

AND p.started_on >= #{startedOnFrom}
AND p.started_on <= #{startedOnTo}

    AND (p.name LIKE CONCAT('%', #{keyword}, '%')
    OR p.client_name LIKE CONCAT('%', #{keyword}, '%'))
